Cypher query: MATCH (robert:Person), (bill:Person)
WHERE (toLower(robert.name) CONTAINS 'robert suettinger' OR any(alias IN coalesce(robert.aliases, []) WHERE toLower(alias) CONTAINS 'robert suettinger'))
  AND (toLower(bill.name) CONTAINS 'bill clinton' OR any(alias IN coalesce(bill.aliases, []) WHERE toLower(alias) CONTAINS 'bill clinton'))
OPTIONAL MATCH connectionPath = (robert)-[*1..3]-(bill)
OPTIONAL MATCH (bill)-[office:MEMBER_OF]->(arkansas:Place)
WHERE toLower(arkansas.name) CONTAINS 'arkansas' OR any(alias IN coalesce(arkansas.aliases, []) WHERE toLower(alias) CONTAINS 'arkansas')
RETURN robert.name AS person, bill.name AS connected_person,
       [node IN nodes(connectionPath) | node.name] AS connection,
       [rel IN relationships(connectionPath) | type(rel)] AS relationships,
       office.role AS role, arkansas.name AS place
LIMIT 10
